"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["28319"],{6014(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.unidade_administradora_sem_cidade","status":422,"titulo":"Unidade administradora n\xe3o tem cidade cadastrada"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.unidade_administradora_sem_cidade","requisitos":["UNI-REQ-0119"],"oQueAconteceu":["Ao criar o processo seletivo, a unidade administradora escolhida n\xe3o tem cidade\\ncadastrada. O processo guarda uma c\xf3pia dos dados da unidade, inclusive a cidade,\\ne a unidade sem cidade no cadastro \xe9 recusada. A mensagem da resposta traz o\\nidentificador da unidade. Nada \xe9 criado.","Essa cidade \xe9 a da unidade e n\xe3o se confunde com a localidade que rege a contagem\\ndos prazos do processo, que \xe9 declarada na pr\xf3pria cria\xe7\xe3o e tem recusa \xe0 parte\\n([localidade ausente](/erros/uniplus.selecao.processo_seletivo.localidade_ausente)).\\nA corre\xe7\xe3o desta recusa fica no cadastro da unidade, e n\xe3o no formul\xe1rio do\\nprocesso."],"comoResolver":["Pe\xe7a a quem mant\xe9m o cadastro de unidades que informe a cidade da unidade\\nadministradora, e crie o processo depois. Como o processo guarda uma c\xf3pia da\\nunidade tirada no momento da cria\xe7\xe3o, a corre\xe7\xe3o no cadastro vale para processos\\ncriados a partir dela; a c\xf3pia de um processo j\xe1 criado n\xe3o \xe9 alterada."],"ondeAparece":["Cria\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);